    private static IEnumerable<(string En, string[] T)> ExtraRows4() => new[]
    {
        R("The ECU refused (7F 3B 22 — conditions not correct). Try: ignition ON, engine/READY off, car in P.", "ECU reddetti (7F 3B 22 — koşullar doğru değil). Deneyin: kontak AÇIK, motor/READY kapalı, araç P'de.", "Die ECU hat abgelehnt (7F 3B 22 – Bedingungen nicht erfüllt). Versuche: Zündung AN, Motor/READY aus, Auto in P.", "ECU odmówiło (7F 3B 22 — warunki niespełnione). Spróbuj: zapłon WŁ., silnik/READY wył., samochód w P.", "La ECU lo rechazó (7F 3B 22: condiciones incorrectas). Prueba: contacto puesto, motor/READY apagado, coche en P.", "A ECU recusou (7F 3B 22 — condições incorretas). Tente: ignição ligada, motor/READY desligado, carro em P.", "L'ECU a refusé (7F 3B 22 — conditions incorrectes). Essayez : contact mis, moteur/READY éteint, voiture en P.", "L'ECU ha rifiutato (7F 3B 22: condizioni non corrette). Prova: quadro acceso, motore/READY spento, auto in P."),
        R("The ECU refused (7F 3B 33 — protected by Security Access). On this car do the reset by hand with the instructions below.", "ECU reddetti (7F 3B 33 — Güvenlik Erişimi ile korunuyor). Bu araçta sıfırlamayı aşağıdaki talimatlarla elle yapın.", "Die ECU hat abgelehnt (7F 3B 33 – durch Security Access geschützt). Führe den Reset bei diesem Auto von Hand nach der Anleitung unten durch.", "ECU odmówiło (7F 3B 33 — chronione przez Security Access). W tym samochodzie wykonaj reset ręcznie według instrukcji poniżej.", "La ECU lo rechazó (7F 3B 33: protegido por Security Access). En este coche haz el restablecimiento a mano con las instrucciones de abajo.", "A ECU recusou (7F 3B 33 — protegido por Security Access). Neste carro faça a reposição à mão com as instruções abaixo.", "L'ECU a refusé (7F 3B 33 — protégé par Security Access). Sur cette voiture, faites la réinitialisation à la main avec les instructions ci-dessous.", "L'ECU ha rifiutato (7F 3B 33: protetto da Security Access). Su questa auto esegui il reset a mano con le istruzioni qui sotto."),
        R("The ECU refused (7F 3B 31 — this value is not writable).", "ECU reddetti (7F 3B 31 — bu değer yazılamaz).", "Die ECU hat abgelehnt (7F 3B 31 – dieser Wert ist nicht beschreibbar).", "ECU odmówiło (7F 3B 31 — ta wartość nie jest zapisywalna).", "La ECU lo rechazó (7F 3B 31: este valor no se puede escribir).", "A ECU recusou (7F 3B 31 — este valor não é gravável).", "L'ECU a refusé (7F 3B 31 — cette valeur n'est pas inscriptible).", "L'ECU ha rifiutato (7F 3B 31: questo valore non è scrivibile)."),
        R("Service reminder reset", "Servis hatırlatıcısı sıfırlama", "Service-Erinnerung zurücksetzen", "Reset przypomnienia serwisowego", "Restablecer recordatorio de servicio", "Repor lembrete de serviço", "Réinitialisation du rappel d'entretien", "Azzeramento promemoria tagliando"),
        R("Compatibility confirmed:", "Uyumluluk doğrulandı:", "Kompatibilität bestätigt:", "Zgodność potwierdzona:", "Compatibilidad confirmada:", "Compatibilidade confirmada:", "Compatibilité confirmée :", "Compatibilità confermata:"),
        R("Current state:", "Mevcut durum:", "Aktueller Zustand:", "Stan bieżący:", "Estado actual:", "Estado atual:", "État actuel :", "Stato attuale:"),
        R("Choose a service action:", "Bir servis işlemi seçin:", "Wähle eine Service-Aktion:", "Wybierz czynność serwisową:", "Elige una acción de servicio:", "Escolha uma ação de serviço:", "Choisissez une action d'entretien :", "Scegli un'azione di servizio:"),
        R("Attention! Use Reset only after the matching service has been done.", "Dikkat! Sıfırlamayı yalnızca ilgili servis yapıldıktan sonra kullanın.", "Achtung! Verwende Zurücksetzen nur, nachdem der passende Service durchgeführt wurde.", "Uwaga! Używaj resetu tylko po wykonaniu odpowiedniego serwisu.", "¡Atención! Usa el restablecimiento solo después de haber hecho el servicio correspondiente.", "Atenção! Use a reposição apenas depois de feito o serviço correspondente.", "Attention ! N'utilisez la réinitialisation qu'après avoir effectué l'entretien correspondant.", "Attenzione! Usa il reset solo dopo aver eseguito il servizio corrispondente."),
        R("Only oil/service values actually read from the ECU", "Yalnızca ECU'dan gerçekten okunan yağ/servis değerleri", "Nur tatsächlich aus der ECU gelesene Öl-/Servicewerte", "Tylko wartości oleju/serwisu faktycznie odczytane z ECU", "Solo valores de aceite/servicio realmente leídos de la ECU", "Apenas valores de óleo/serviço realmente lidos da ECU", "Uniquement les valeurs d'huile/d'entretien réellement lues dans l'ECU", "Solo valori di olio/servizio realmente letti dall'ECU"),
        R("This car did not return a confirmed Service value on this connection.", "Bu araç bu bağlantıda doğrulanmış bir Servis değeri döndürmedi.", "Dieses Auto lieferte über diese Verbindung keinen bestätigten Servicewert.", "Ten samochód nie zwrócił potwierdzonej wartości serwisowej na tym połączeniu.", "Este coche no devolvió un valor de servicio confirmado en esta conexión.", "Este carro não devolveu um valor de serviço confirmado nesta ligação.", "Cette voiture n'a pas renvoyé de valeur d'entretien confirmée sur cette connexion.", "Questa auto non ha restituito un valore di servizio confermato su questa connessione."),
        R("The button appears only when a reviewed reset operation is found for the exact vehicle/ECU. After success the value is read again from the ECU.", "Düğme yalnızca tam araç/ECU için incelenmiş bir sıfırlama işlemi bulunduğunda görünür. Başarıdan sonra değer ECU'dan yeniden okunur.", "Die Schaltfläche erscheint nur, wenn für genau dieses Fahrzeug/diese ECU ein geprüfter Reset-Vorgang gefunden wird. Nach dem Erfolg wird der Wert erneut aus der ECU gelesen.", "Przycisk pojawia się tylko wtedy, gdy dla dokładnie tego pojazdu/ECU znaleziono zweryfikowaną operację resetu. Po sukcesie wartość jest ponownie odczytywana z ECU.", "El botón aparece solo cuando se encuentra una operación de restablecimiento revisada para el vehículo/ECU exactos. Tras el éxito, el valor se vuelve a leer de la ECU.", "O botão só aparece quando é encontrada uma operação de reposição revista para o veículo/ECU exatos. Após o sucesso, o valor é lido de novo da ECU.", "Le bouton n'apparaît que lorsqu'une opération de réinitialisation vérifiée est trouvée pour le véhicule/l'ECU exact. Après réussite, la valeur est relue dans l'ECU.", "Il pulsante compare solo quando viene trovata un'operazione di reset verificata per l'esatto veicolo/ECU. Dopo il successo il valore viene riletto dall'ECU."),
        R("These are confirmed manual procedures for the car. They do not send a write command to the ECU.", "Bunlar araç için doğrulanmış manuel prosedürlerdir. ECU'ya yazma komutu göndermezler.", "Dies sind bestätigte manuelle Verfahren für das Auto. Sie senden keinen Schreibbefehl an die ECU.", "To potwierdzone procedury ręczne dla tego samochodu. Nie wysyłają do ECU polecenia zapisu.", "Estos son procedimientos manuales confirmados para el coche. No envían ningún comando de escritura a la ECU.", "Estes são procedimentos manuais confirmados para o carro. Não enviam nenhum comando de escrita à ECU.", "Ce sont des procédures manuelles confirmées pour la voiture. Elles n'envoient aucune commande d'écriture à l'ECU.", "Sono procedure manuali confermate per l'auto. Non inviano alcun comando di scrittura all'ECU."),
        R("No guided procedure found for this car.", "Bu araç için yönlendirmeli prosedür bulunamadı.", "Für dieses Auto wurde kein geführtes Verfahren gefunden.", "Dla tego samochodu nie znaleziono procedury z przewodnikiem.", "No se encontró ningún procedimiento guiado para este coche.", "Não foi encontrado nenhum procedimento guiado para este carro.", "Aucune procédure guidée trouvée pour cette voiture.", "Nessuna procedura guidata trovata per questa auto."),
        R("Real ECU data · dynamic functions · verification after Reset", "Gerçek ECU verileri · dinamik işlevler · Sıfırlama sonrası doğrulama", "Echte ECU-Daten · dynamische Funktionen · Überprüfung nach dem Zurücksetzen", "Rzeczywiste dane ECU · funkcje dynamiczne · weryfikacja po resecie", "Datos reales de la ECU · funciones dinámicas · verificación tras el restablecimiento", "Dados reais da ECU · funções dinâmicas · verificação após a reposição", "Données ECU réelles · fonctions dynamiques · vérification après réinitialisation", "Dati ECU reali · funzioni dinamiche · verifica dopo il reset"),
        R("Service data unavailable", "Servis verileri kullanılamıyor", "Servicedaten nicht verfügbar", "Dane serwisowe niedostępne", "Datos de servicio no disponibles", "Dados de serviço indisponíveis", "Données d'entretien indisponibles", "Dati di servizio non disponibili"),
        R("This car did not return a supported service value on this connection.", "Bu araç bu bağlantıda desteklenen bir servis değeri döndürmedi.", "Dieses Auto lieferte über diese Verbindung keinen unterstützten Servicewert.", "Ten samochód nie zwrócił obsługiwanej wartości serwisowej na tym połączeniu.", "Este coche no devolvió un valor de servicio compatible en esta conexión.", "Este carro não devolveu um valor de serviço suportado nesta ligação.", "Cette voiture n'a pas renvoyé de valeur d'entretien prise en charge sur cette connexion.", "Questa auto non ha restituito un valore di servizio supportato su questa connessione."),
        R("Only Adaptation, Coding and Active Test functions found on this exact car/ECU.", "Yalnızca bu tam araç/ECU'da bulunan Adaptasyon, Kodlama ve Aktif Test işlevleri.", "Nur Anpassungs-, Codierungs- und Aktivtest-Funktionen, die bei genau diesem Auto/dieser ECU gefunden wurden.", "Tylko funkcje adaptacji, kodowania i testu aktywnego znalezione dla dokładnie tego samochodu/ECU.", "Solo funciones de adaptación, codificación y prueba activa encontradas en este coche/ECU exactos.", "Apenas funções de adaptação, codificação e teste ativo encontradas neste carro/ECU exatos.", "Seules les fonctions d'adaptation, de codage et de test actif trouvées pour cette voiture/ECU exacte.", "Solo funzioni di adattamento, codifica e test attivo trovate su questa esatta auto/ECU."),
        R("Only confirmed Service Reset, Adaptation, Coding and Active Test functions", "Yalnızca doğrulanmış Servis Sıfırlama, Adaptasyon, Kodlama ve Aktif Test işlevleri", "Nur bestätigte Service-Reset-, Anpassungs-, Codierungs- und Aktivtest-Funktionen", "Tylko potwierdzone funkcje resetu serwisu, adaptacji, kodowania i testu aktywnego", "Solo funciones confirmadas de restablecimiento de servicio, adaptación, codificación y prueba activa", "Apenas funções confirmadas de reposição de serviço, adaptação, codificação e teste ativo", "Uniquement les fonctions confirmées de réinitialisation d'entretien, d'adaptation, de codage et de test actif", "Solo funzioni confermate di reset servizio, adattamento, codifica e test attivo"),
        R("This is the current read-only snapshot. Each operation re-checks its conditions before it runs.", "Bu, mevcut salt okunur anlık görüntüdür. Her işlem çalışmadan önce koşullarını yeniden kontrol eder.", "Dies ist der aktuelle schreibgeschützte Schnappschuss. Jeder Vorgang prüft seine Bedingungen vor der Ausführung erneut.", "To bieżąca migawka tylko do odczytu. Każda operacja ponownie sprawdza swoje warunki przed uruchomieniem.", "Esta es la instantánea actual de solo lectura. Cada operación vuelve a comprobar sus condiciones antes de ejecutarse.", "Este é o instantâneo atual só de leitura. Cada operação volta a verificar as suas condições antes de ser executada.", "Il s'agit de l'instantané actuel en lecture seule. Chaque opération revérifie ses conditions avant de s'exécuter.", "Questa è l'istantanea attuale di sola lettura. Ogni operazione ricontrolla le proprie condizioni prima di essere eseguita."),
        R("Oil service, EPB and other exactly confirmed service procedures", "Yağ servisi, EPB ve diğer tam olarak doğrulanmış servis prosedürleri", "Ölservice, EPB und andere genau bestätigte Serviceverfahren", "Serwis oleju, EPB i inne dokładnie potwierdzone procedury serwisowe", "Servicio de aceite, EPB y otros procedimientos de servicio exactamente confirmados", "Serviço de óleo, EPB e outros procedimentos de serviço exatamente confirmados", "Entretien de l'huile, EPB et autres procédures d'entretien exactement confirmées", "Servizio olio, EPB e altre procedure di servizio esattamente confermate"),
        R("Calibration, relearn and adaptation procedures only from operations confirmed in the catalog", "Kalibrasyon, yeniden öğrenme ve adaptasyon prosedürleri yalnızca katalogda doğrulanmış işlemlerden", "Kalibrierungs-, Einlern- und Anpassungsverfahren nur aus im Katalog bestätigten Vorgängen", "Procedury kalibracji, ponownego uczenia i adaptacji tylko z operacji potwierdzonych w katalogu", "Procedimientos de calibración, reaprendizaje y adaptación solo a partir de operaciones confirmadas en el catálogo", "Procedimentos de calibração, reaprendizagem e adaptação apenas a partir de operações confirmadas no catálogo", "Procédures d'étalonnage, de réapprentissage et d'adaptation uniquement à partir d'opérations confirmées dans le catalogue", "Procedure di calibrazione, riapprendimento e adattamento solo da operazioni confermate nel catalogo"),
        R("Coding only on an exact OEM definition: backup → write → verify", "Kodlama yalnızca tam bir OEM tanımında: yedek → yaz → doğrula", "Codierung nur bei einer exakten OEM-Definition: Sicherung → Schreiben → Prüfen", "Kodowanie tylko na dokładnej definicji OEM: kopia → zapis → weryfikacja", "Codificación solo con una definición OEM exacta: copia → escritura → verificación", "Codificação apenas com uma definição OEM exata: cópia → escrita → verificação", "Codage uniquement sur une définition OEM exacte : sauvegarde → écriture → vérification", "Codifica solo su una definizione OEM esatta: backup → scrittura → verifica"),
        R("The test runs only with a reviewed ECU command and a safe STOP command", "Test yalnızca incelenmiş bir ECU komutu ve güvenli bir DURDUR komutuyla çalışır", "Der Test läuft nur mit einem geprüften ECU-Befehl und einem sicheren STOPP-Befehl", "Test działa tylko ze zweryfikowanym poleceniem ECU i bezpiecznym poleceniem STOP", "La prueba solo se ejecuta con un comando de ECU revisado y un comando STOP seguro", "O teste só é executado com um comando ECU revisto e um comando STOP seguro", "Le test ne s'exécute qu'avec une commande ECU vérifiée et une commande STOP sûre", "Il test viene eseguito solo con un comando ECU verificato e un comando STOP sicuro"),
        R("No confirmed Service Reset is available for this car yet.", "Bu araç için henüz doğrulanmış bir Servis Sıfırlama yok.", "Für dieses Auto ist noch kein bestätigter Service-Reset verfügbar.", "Dla tego samochodu nie ma jeszcze potwierdzonego resetu serwisu.", "Aún no hay un restablecimiento de servicio confirmado para este coche.", "Ainda não existe uma reposição de serviço confirmada para este carro.", "Aucune réinitialisation d'entretien confirmée n'est encore disponible pour cette voiture.", "Non è ancora disponibile un reset servizio confermato per questa auto."),
        R("No confirmed Adaptation is available for this car yet.", "Bu araç için henüz doğrulanmış bir Adaptasyon yok.", "Für dieses Auto ist noch keine bestätigte Anpassung verfügbar.", "Dla tego samochodu nie ma jeszcze potwierdzonej adaptacji.", "Aún no hay una adaptación confirmada para este coche.", "Ainda não existe uma adaptação confirmada para este carro.", "Aucune adaptation confirmée n'est encore disponible pour cette voiture.", "Non è ancora disponibile un adattamento confermato per questa auto."),
        R("No confirmed Coding function is available for this car yet.", "Bu araç için henüz doğrulanmış bir Kodlama işlevi yok.", "Für dieses Auto ist noch keine bestätigte Codierfunktion verfügbar.", "Dla tego samochodu nie ma jeszcze potwierdzonej funkcji kodowania.", "Aún no hay una función de codificación confirmada para este coche.", "Ainda não existe uma função de codificação confirmada para este carro.", "Aucune fonction de codage confirmée n'est encore disponible pour cette voiture.", "Non è ancora disponibile una funzione di codifica confermata per questa auto."),
        R("No confirmed Active Test is available for this car yet.", "Bu araç için henüz doğrulanmış bir Aktif Test yok.", "Für dieses Auto ist noch kein bestätigter Aktivtest verfügbar.", "Dla tego samochodu nie ma jeszcze potwierdzonego testu aktywnego.", "Aún no hay una prueba activa confirmada para este coche.", "Ainda não existe um teste ativo confirmado para este carro.", "Aucun test actif confirmé n'est encore disponible pour cette voiture.", "Non è ancora disponibile un test attivo confermato per questa auto."),
        R("The app does not send guessed OEM commands. A function is enabled only when the exact car, ECU definition, address, voltage and required runtime conditions are confirmed. If Security Access is needed, the function stays locked until the matching authorisation exists.", "Uygulama tahmin edilen OEM komutları göndermez. Bir işlev yalnızca tam araç, ECU tanımı, adres, voltaj ve gerekli çalışma koşulları doğrulandığında etkinleşir. Güvenlik Erişimi gerekiyorsa, uygun yetkilendirme olana kadar işlev kilitli kalır.", "Die App sendet keine erratenen OEM-Befehle. Eine Funktion wird nur aktiviert, wenn genaues Auto, ECU-Definition, Adresse, Spannung und die nötigen Laufzeitbedingungen bestätigt sind. Wird Security Access benötigt, bleibt die Funktion gesperrt, bis die passende Autorisierung vorliegt.", "Aplikacja nie wysyła zgadywanych poleceń OEM. Funkcja jest włączana tylko wtedy, gdy potwierdzono dokładny samochód, definicję ECU, adres, napięcie i wymagane warunki działania. Jeśli potrzebny jest Security Access, funkcja pozostaje zablokowana, dopóki nie pojawi się odpowiednia autoryzacja.", "La app no envía comandos OEM supuestos. Una función solo se activa cuando se confirman el coche exacto, la definición de la ECU, la dirección, el voltaje y las condiciones de ejecución necesarias. Si se necesita Security Access, la función permanece bloqueada hasta que exista la autorización correspondiente.", "A app não envia comandos OEM presumidos. Uma função só é ativada quando o carro exato, a definição da ECU, o endereço, a tensão e as condições de execução necessárias estão confirmados. Se for necessário Security Access, a função permanece bloqueada até existir a autorização correspondente.", "L'application n'envoie pas de commandes OEM supposées. Une fonction n'est activée que lorsque la voiture exacte, la définition de l'ECU, l'adresse, la tension et les conditions d'exécution requises sont confirmées. Si un Security Access est nécessaire, la fonction reste verrouillée tant que l'autorisation correspondante n'existe pas.", "L'app non invia comandi OEM ipotetici. Una funzione viene abilitata solo quando sono confermati l'auto esatta, la definizione ECU, l'indirizzo, la tensione e le condizioni di esecuzione richieste. Se serve il Security Access, la funzione resta bloccata finché non esiste l'autorizzazione corrispondente."),
        R("If the oil % is not shown above: enter the % shown on the car's screen and press search. The app only reads (0x22) and writes nothing. A deep search takes a few minutes — keep the ignition on.", "Yağ % yukarıda gösterilmiyorsa: aracın ekranında gösterilen %'yi girin ve aramaya basın. Uygulama yalnızca okur (0x22) ve hiçbir şey yazmaz. Derin arama birkaç dakika sürer — kontağı açık tutun.", "Wenn der Öl-% oben nicht angezeigt wird: Gib den auf dem Fahrzeugbildschirm angezeigten % ein und tippe auf Suchen. Die App liest nur (0x22) und schreibt nichts. Eine tiefe Suche dauert einige Minuten – lass die Zündung an.", "Jeśli % oleju nie jest pokazany powyżej: wpisz % widoczny na ekranie samochodu i naciśnij szukaj. Aplikacja tylko odczytuje (0x22) i niczego nie zapisuje. Dokładne wyszukiwanie trwa kilka minut — zostaw zapłon włączony.", "Si el % de aceite no se muestra arriba: introduce el % que aparece en la pantalla del coche y pulsa buscar. La app solo lee (0x22) y no escribe nada. Una búsqueda profunda tarda unos minutos: deja el contacto puesto.", "Se a % de óleo não for mostrada acima: introduza a % apresentada no ecrã do carro e prima pesquisar. A app só lê (0x22) e não escreve nada. Uma pesquisa profunda demora alguns minutos — mantenha a ignição ligada.", "Si le % d'huile n'est pas affiché ci-dessus : saisissez le % indiqué à l'écran de la voiture et appuyez sur rechercher. L'application ne fait que lire (0x22) et n'écrit rien. Une recherche approfondie prend quelques minutes — laissez le contact mis.", "Se la % di olio non è mostrata sopra: inserisci la % indicata sullo schermo dell'auto e premi cerca. L'app legge soltanto (0x22) e non scrive nulla. Una ricerca approfondita richiede alcuni minuti: lascia il quadro acceso."),
        R("Resetting from the app is not available on this car yet — use the instructions below.", "Uygulamadan sıfırlama bu araçta henüz mevcut değil — aşağıdaki talimatları kullanın.", "Das Zurücksetzen über die App ist bei diesem Auto noch nicht verfügbar – nutze die Anleitung unten.", "Reset z poziomu aplikacji nie jest jeszcze dostępny w tym samochodzie — skorzystaj z instrukcji poniżej.", "El restablecimiento desde la app aún no está disponible en este coche: usa las instrucciones de abajo.", "A reposição a partir da app ainda não está disponível neste carro — use as instruções abaixo.", "La réinitialisation depuis l'application n'est pas encore disponible sur cette voiture — utilisez les instructions ci-dessous.", "Il reset dall'app non è ancora disponibile su questa auto: usa le istruzioni qui sotto."),
        R("Checking the OBD adapter and ECU…", "OBD adaptörü ve ECU kontrol ediliyor…", "OBD-Adapter und ECU werden geprüft…", "Sprawdzanie adaptera OBD i ECU…", "Comprobando el adaptador OBD y la ECU…", "A verificar o adaptador OBD e a ECU…", "Vérification de l'adaptateur OBD et de l'ECU…", "Verifica dell'adattatore OBD e dell'ECU…"),
        R("Reading service data…", "Servis verileri okunuyor…", "Servicedaten werden gelesen…", "Odczyt danych serwisowych…", "Leyendo datos de servicio…", "A ler os dados de serviço…", "Lecture des données d'entretien…", "Lettura dei dati di servizio…"),
        R("A real Generic OBD-II ECU reply could not be confirmed, so no Service/Coding command will be sent.", "Gerçek bir Genel OBD-II ECU yanıtı doğrulanamadı, bu yüzden hiçbir Servis/Kodlama komutu gönderilmeyecek.", "Eine echte generische OBD-II-ECU-Antwort konnte nicht bestätigt werden, daher wird kein Service-/Codierbefehl gesendet.", "Nie potwierdzono rzeczywistej odpowiedzi ogólnego ECU OBD-II, więc nie zostanie wysłane żadne polecenie serwisowe/kodowania.", "No se pudo confirmar una respuesta real de ECU OBD-II genérica, por lo que no se enviará ningún comando de servicio/codificación.", "Não foi possível confirmar uma resposta real de ECU OBD-II genérica, por isso nenhum comando de serviço/codificação será enviado.", "Une réponse réelle d'ECU OBD-II générique n'a pas pu être confirmée ; aucune commande d'entretien/de codage ne sera donc envoyée.", "Non è stato possibile confermare una risposta reale di ECU OBD-II generica, quindi non verrà inviato alcun comando di servizio/codifica."),
        R("The ECU answers, but the VIN/manufacturer/model could not be confirmed well enough.", "ECU yanıt veriyor, ancak VIN/üretici/model yeterince doğrulanamadı.", "Die ECU antwortet, aber VIN/Hersteller/Modell konnten nicht ausreichend bestätigt werden.", "ECU odpowiada, ale VIN/producent/model nie zostały wystarczająco potwierdzone.", "La ECU responde, pero el VIN/fabricante/modelo no se pudo confirmar lo suficiente.", "A ECU responde, mas o VIN/fabricante/modelo não pôde ser confirmado o suficiente.", "L'ECU répond, mais le VIN/constructeur/modèle n'a pas pu être suffisamment confirmé.", "L'ECU risponde, ma VIN/costruttore/modello non hanno potuto essere confermati a sufficienza."),
        R("OEM profile not confirmed", "OEM profili doğrulanmadı", "OEM-Profil nicht bestätigt", "Profil OEM niepotwierdzony", "Perfil OEM no confirmado", "Perfil OEM não confirmado", "Profil OEM non confirmé", "Profilo OEM non confermato"),
        R("This car did not return a supported service value.", "Bu araç desteklenen bir servis değeri döndürmedi.", "Dieses Auto lieferte keinen unterstützten Servicewert.", "Ten samochód nie zwrócił obsługiwanej wartości serwisowej.", "Este coche no devolvió un valor de servicio compatible.", "Este carro não devolveu um valor de serviço suportado.", "Cette voiture n'a pas renvoyé de valeur d'entretien prise en charge.", "Questa auto non ha restituito un valore di servizio supportato."),
        R("Below are the service reset instructions for your car. Press “Instructions”.", "Aşağıda aracınız için servis sıfırlama talimatları yer alır. “Talimatlar”a basın.", "Unten findest du die Service-Reset-Anleitung für dein Auto. Tippe auf „Anleitung“.", "Poniżej znajdują się instrukcje resetu serwisu dla Twojego samochodu. Naciśnij „Instrukcje”.", "Abajo están las instrucciones de restablecimiento de servicio para tu coche. Pulsa «Instrucciones».", "Abaixo estão as instruções de reposição de serviço para o seu carro. Prima «Instruções».", "Voici les instructions de réinitialisation d'entretien pour votre voiture. Appuyez sur « Instructions ».", "Qui sotto ci sono le istruzioni di reset del servizio per la tua auto. Premi «Istruzioni»."),
        R("Vehicle information must be loaded first.", "Önce araç bilgileri yüklenmelidir.", "Die Fahrzeuginformationen müssen zuerst geladen werden.", "Najpierw trzeba wczytać informacje o pojeździe.", "Primero hay que cargar la información del vehículo.", "As informações do veículo têm de ser carregadas primeiro.", "Les informations du véhicule doivent d'abord être chargées.", "Prima vanno caricate le informazioni sul veicolo."),
        R("Reading OEM data…", "OEM verileri okunuyor…", "OEM-Daten werden gelesen…", "Odczyt danych OEM…", "Leyendo datos OEM…", "A ler dados OEM…", "Lecture des données OEM…", "Lettura dei dati OEM…"),
        R("OEM data saved:", "OEM verileri kaydedildi:", "OEM-Daten gespeichert:", "Dane OEM zapisane:", "Datos OEM guardados:", "Dados OEM guardados:", "Données OEM enregistrées :", "Dati OEM salvati:"),
        R("The OBD adapter is not ready. Connect to the adapter first.", "OBD adaptörü hazır değil. Önce adaptöre bağlanın.", "Der OBD-Adapter ist nicht bereit. Verbinde dich zuerst mit dem Adapter.", "Adapter OBD nie jest gotowy. Najpierw połącz się z adapterem.", "El adaptador OBD no está listo. Conéctate primero al adaptador.", "O adaptador OBD não está pronto. Ligue-se primeiro ao adaptador.", "L'adaptateur OBD n'est pas prêt. Connectez-vous d'abord à l'adaptateur.", "L'adattatore OBD non è pronto. Connettiti prima all'adattatore."),
        R("The adapter is connected, but the car's Generic OBD-II ECU reply could not be confirmed.", "Adaptör bağlı, ancak aracın Genel OBD-II ECU yanıtı doğrulanamadı.", "Der Adapter ist verbunden, aber die generische OBD-II-ECU-Antwort des Autos konnte nicht bestätigt werden.", "Adapter jest połączony, ale nie potwierdzono odpowiedzi ogólnego ECU OBD-II samochodu.", "El adaptador está conectado, pero no se pudo confirmar la respuesta de la ECU OBD-II genérica del coche.", "O adaptador está ligado, mas não foi possível confirmar a resposta da ECU OBD-II genérica do carro.", "L'adaptateur est connecté, mais la réponse de l'ECU OBD-II générique de la voiture n'a pas pu être confirmée.", "L'adattatore è connesso, ma non è stato possibile confermare la risposta dell'ECU OBD-II generica dell'auto."),
        R("Adapter and Generic OBD-II ECU reply confirmed. OEM functions are checked separately with an exact definition.", "Adaptör ve Genel OBD-II ECU yanıtı doğrulandı. OEM işlevleri tam bir tanımla ayrıca kontrol edilir.", "Adapter und generische OBD-II-ECU-Antwort bestätigt. OEM-Funktionen werden separat mit einer exakten Definition geprüft.", "Adapter i odpowiedź ogólnego ECU OBD-II potwierdzone. Funkcje OEM są sprawdzane osobno z dokładną definicją.", "Adaptador y respuesta de la ECU OBD-II genérica confirmados. Las funciones OEM se comprueban por separado con una definición exacta.", "Adaptador e resposta da ECU OBD-II genérica confirmados. As funções OEM são verificadas em separado com uma definição exata.", "Adaptateur et réponse de l'ECU OBD-II générique confirmés. Les fonctions OEM sont vérifiées séparément avec une définition exacte.", "Adattatore e risposta dell'ECU OBD-II generica confermati. Le funzioni OEM vengono verificate separatamente con una definizione esatta."),
        R("GUIDED · no ECU write is sent", "YÖNLENDİRMELİ · ECU'ya yazma gönderilmez", "GEFÜHRT · es wird nichts in die ECU geschrieben", "Z PRZEWODNIKIEM · do ECU nic nie jest zapisywane", "GUIADO · no se envía ninguna escritura a la ECU", "GUIADO · nenhuma escrita é enviada à ECU", "GUIDÉ · aucune écriture n'est envoyée à l'ECU", "GUIDATO · nessuna scrittura viene inviata all'ECU"),
        R("The oil service count will restart from today. Press it only after an oil change.", "Yağ servisi sayacı bugünden yeniden başlayacak. Yalnızca yağ değişiminden sonra basın.", "Der Ölservice-Zähler beginnt ab heute neu. Drücke nur nach einem Ölwechsel.", "Licznik serwisu oleju zacznie liczyć od dziś. Naciśnij dopiero po wymianie oleju.", "El contador del servicio de aceite se reiniciará desde hoy. Púlsalo solo después de un cambio de aceite.", "A contagem do serviço de óleo recomeçará a partir de hoje. Prima apenas depois de uma mudança de óleo.", "Le compteur d'entretien de l'huile repartira d'aujourd'hui. N'appuyez qu'après une vidange.", "Il conteggio del servizio olio ripartirà da oggi. Premilo solo dopo un cambio dell'olio."),
        R("The car's odometer cannot be read now. Connect the adapter, turn the ignition on and try again.", "Aracın kilometre sayacı şu anda okunamıyor. Adaptörü bağlayın, kontağı açın ve tekrar deneyin.", "Der Kilometerzähler des Autos kann jetzt nicht gelesen werden. Verbinde den Adapter, schalte die Zündung ein und versuche es erneut.", "Nie można teraz odczytać licznika przebiegu samochodu. Podłącz adapter, włącz zapłon i spróbuj ponownie.", "Ahora no se puede leer el cuentakilómetros del coche. Conecta el adaptador, pon el contacto y vuelve a intentarlo.", "Não é possível ler agora o conta-quilómetros do carro. Ligue o adaptador, ligue a ignição e tente novamente.", "Le compteur kilométrique de la voiture ne peut pas être lu pour le moment. Connectez l'adaptateur, mettez le contact et réessayez.", "Al momento non è possibile leggere il contachilometri dell'auto. Connetti l'adattatore, accendi il quadro e riprova."),
        R("Do it only after the service has been done.", "Bunu yalnızca servis yapıldıktan sonra yapın.", "Nur durchführen, nachdem der Service erledigt wurde.", "Wykonuj to dopiero po wykonaniu serwisu.", "Hazlo solo después de haber hecho el servicio.", "Faça-o apenas depois de feito o serviço.", "À faire uniquement après l'entretien.", "Eseguilo solo dopo aver fatto il servizio."),
        R("Car in P, ignition on.", "Araç P'de, kontak açık.", "Auto in P, Zündung an.", "Samochód w P, zapłon włączony.", "Coche en P, contacto puesto.", "Carro em P, ignição ligada.", "Voiture en P, contact mis.", "Auto in P, quadro acceso."),
        R("First press “Check” and confirm the car/ECU.", "Önce “Kontrol et”e basın ve aracı/ECU'yu onaylayın.", "Tippe zuerst auf „Prüfen“ und bestätige das Auto/die ECU.", "Najpierw naciśnij „Sprawdź” i potwierdź samochód/ECU.", "Primero pulsa «Comprobar» y confirma el coche/ECU.", "Prima primeiro «Verificar» e confirme o carro/ECU.", "Appuyez d'abord sur « Vérifier » et confirmez la voiture/l'ECU.", "Premi prima «Controlla» e conferma l'auto/ECU."),
        R("Do you really want to reset Oil Life?", "Yağ Ömrünü gerçekten sıfırlamak istiyor musunuz?", "Möchtest du die Öllebensdauer wirklich zurücksetzen?", "Czy na pewno chcesz zresetować żywotność oleju?", "¿Seguro que quieres restablecer la vida del aceite?", "Tem a certeza de que quer repor a vida útil do óleo?", "Voulez-vous vraiment réinitialiser la durée de vie de l'huile ?", "Vuoi davvero azzerare la vita dell'olio?"),
        R("Before running, the app will re-check voltage, speed, engine state and the exact ECU definition. Continue?", "Çalıştırmadan önce uygulama voltajı, hızı, motor durumunu ve tam ECU tanımını yeniden kontrol edecek. Devam edilsin mi?", "Vor der Ausführung prüft die App Spannung, Geschwindigkeit, Motorzustand und die exakte ECU-Definition erneut. Fortfahren?", "Przed uruchomieniem aplikacja ponownie sprawdzi napięcie, prędkość, stan silnika i dokładną definicję ECU. Kontynuować?", "Antes de ejecutar, la app volverá a comprobar el voltaje, la velocidad, el estado del motor y la definición exacta de la ECU. ¿Continuar?", "Antes de executar, a app volta a verificar a tensão, a velocidade, o estado do motor e a definição exata da ECU. Continuar?", "Avant l'exécution, l'application revérifiera la tension, la vitesse, l'état du moteur et la définition exacte de l'ECU. Continuer ?", "Prima dell'esecuzione l'app ricontrollerà tensione, velocità, stato del motore e definizione esatta dell'ECU. Continuare?"),
        R("Active Test stopped. A reviewed STOP command was sent for safety.", "Aktif Test durduruldu. Güvenlik için incelenmiş bir DURDUR komutu gönderildi.", "Aktivtest gestoppt. Zur Sicherheit wurde ein geprüfter STOPP-Befehl gesendet.", "Test aktywny zatrzymany. Dla bezpieczeństwa wysłano zweryfikowane polecenie STOP.", "Prueba activa detenida. Se envió un comando STOP revisado por seguridad.", "Teste ativo parado. Foi enviado um comando STOP revisto por segurança.", "Test actif arrêté. Une commande STOP vérifiée a été envoyée par sécurité.", "Test attivo fermato. Per sicurezza è stato inviato un comando STOP verificato."),
        R("ECU backup saved", "ECU yedeği kaydedildi", "ECU-Sicherung gespeichert", "Kopia zapasowa ECU zapisana", "Copia de seguridad de la ECU guardada", "Cópia de segurança da ECU guardada", "Sauvegarde de l'ECU enregistrée", "Backup dell'ECU salvato"),
        R("Backup: saved just now", "Yedek: az önce kaydedildi", "Sicherung: gerade eben gespeichert", "Kopia: zapisano przed chwilą", "Copia de seguridad: guardada ahora mismo", "Cópia de segurança: guardada agora mesmo", "Sauvegarde : enregistrée à l'instant", "Backup: salvato proprio ora"),
        R("Active Test is stopping — a reviewed STOP command is being sent…", "Aktif Test durduruluyor — incelenmiş bir DURDUR komutu gönderiliyor…", "Aktivtest wird gestoppt – ein geprüfter STOPP-Befehl wird gesendet…", "Test aktywny jest zatrzymywany — wysyłane jest zweryfikowane polecenie STOP…", "La prueba activa se está deteniendo: se envía un comando STOP revisado…", "O teste ativo está a parar — está a ser enviado um comando STOP revisto…", "Le test actif s'arrête — une commande STOP vérifiée est en cours d'envoi…", "Il test attivo si sta fermando: viene inviato un comando STOP verificato…"),
        R("The latest original coding backup for this VIN will be restored. The app will re-check the safety conditions and verify the ECU reply after writing. Continue?", "Bu VIN için en son orijinal kodlama yedeği geri yüklenecek. Uygulama güvenlik koşullarını yeniden kontrol edecek ve yazdıktan sonra ECU yanıtını doğrulayacak. Devam edilsin mi?", "Die neueste ursprüngliche Codierungssicherung für diese VIN wird wiederhergestellt. Die App prüft die Sicherheitsbedingungen erneut und verifiziert nach dem Schreiben die ECU-Antwort. Fortfahren?", "Zostanie przywrócona najnowsza oryginalna kopia kodowania dla tego VIN. Aplikacja ponownie sprawdzi warunki bezpieczeństwa i po zapisie zweryfikuje odpowiedź ECU. Kontynuować?", "Se restaurará la copia de codificación original más reciente de este VIN. La app volverá a comprobar las condiciones de seguridad y verificará la respuesta de la ECU tras escribir. ¿Continuar?", "Será restaurada a cópia de codificação original mais recente deste VIN. A app volta a verificar as condições de segurança e verifica a resposta da ECU após escrever. Continuar?", "La dernière sauvegarde de codage d'origine pour ce VIN sera restaurée. L'application revérifiera les conditions de sécurité et vérifiera la réponse de l'ECU après l'écriture. Continuer ?", "Verrà ripristinato l'ultimo backup originale di codifica per questo VIN. L'app ricontrollerà le condizioni di sicurezza e verificherà la risposta dell'ECU dopo la scrittura. Continuare?"),
        R("The connection/ECU capability check did not finish.", "Bağlantı/ECU yetenek kontrolü tamamlanmadı.", "Die Prüfung der Verbindung/ECU-Funktionen wurde nicht abgeschlossen.", "Sprawdzanie połączenia/możliwości ECU nie zostało ukończone.", "La comprobación de la conexión/capacidades de la ECU no terminó.", "A verificação da ligação/capacidades da ECU não terminou.", "La vérification de la connexion/des capacités de l'ECU ne s'est pas terminée.", "La verifica della connessione/funzionalità dell'ECU non è terminata."),
        R("For safety, no OEM command was sent.", "Güvenlik için hiçbir OEM komutu gönderilmedi.", "Aus Sicherheitsgründen wurde kein OEM-Befehl gesendet.", "Ze względów bezpieczeństwa nie wysłano żadnego polecenia OEM.", "Por seguridad, no se envió ningún comando OEM.", "Por segurança, nenhum comando OEM foi enviado.", "Par sécurité, aucune commande OEM n'a été envoyée.", "Per sicurezza non è stato inviato alcun comando OEM."),
        R("OEM discovery did not finish", "OEM keşfi tamamlanmadı", "OEM-Erkennung nicht abgeschlossen", "Wykrywanie OEM nie zostało ukończone", "El descubrimiento OEM no terminó", "A descoberta OEM não terminou", "La découverte OEM ne s'est pas terminée", "Il rilevamento OEM non è terminato"),
        R("The ECU did not confirm clearing the DTCs.", "ECU, DTC'lerin silindiğini doğrulamadı.", "Die ECU hat das Löschen der DTCs nicht bestätigt.", "ECU nie potwierdziło skasowania DTC.", "La ECU no confirmó el borrado de los DTC.", "A ECU não confirmou a eliminação dos DTC.", "L'ECU n'a pas confirmé l'effacement des DTC.", "L'ECU non ha confermato la cancellazione dei DTC."),
        R("The description of this code was not found in the database (it may be a manufacturer-specific code).", "Bu kodun açıklaması veritabanında bulunamadı (üreticiye özgü bir kod olabilir).", "Die Beschreibung dieses Codes wurde in der Datenbank nicht gefunden (es könnte ein herstellerspezifischer Code sein).", "Opisu tego kodu nie znaleziono w bazie danych (może to być kod specyficzny dla producenta).", "No se encontró la descripción de este código en la base de datos (puede ser un código específico del fabricante).", "A descrição deste código não foi encontrada na base de dados (pode ser um código específico do fabricante).", "La description de ce code n'a pas été trouvée dans la base de données (il peut s'agir d'un code propre au constructeur).", "La descrizione di questo codice non è stata trovata nel database (potrebbe essere un codice specifico del costruttore)."),
        R("Maximum difference:", "Maksimum fark:", "Maximale Abweichung:", "Maksymalna różnica:", "Diferencia máxima:", "Diferença máxima:", "Écart maximal :", "Differenza massima:"),
        R("One source cannot confirm the mileage is original.", "Tek bir kaynak, kilometrenin orijinal olduğunu doğrulayamaz.", "Eine einzelne Quelle kann nicht bestätigen, dass der Kilometerstand original ist.", "Jedno źródło nie może potwierdzić, że przebieg jest oryginalny.", "Una sola fuente no puede confirmar que el kilometraje sea original.", "Uma única fonte não pode confirmar que a quilometragem é original.", "Une seule source ne peut pas confirmer que le kilométrage est d'origine.", "Una sola fonte non può confermare che il chilometraggio sia originale."),
        R("There is a significant difference between ECU sources; this may also be the result of a module replacement or reset.", "ECU kaynakları arasında önemli bir fark var; bu bir modül değişiminin veya sıfırlamanın sonucu da olabilir.", "Zwischen den ECU-Quellen gibt es eine deutliche Abweichung; das kann auch auf einen Modultausch oder Reset zurückgehen.", "Między źródłami ECU jest istotna różnica; może to być także skutek wymiany modułu lub resetu.", "Hay una diferencia significativa entre las fuentes de la ECU; también puede deberse a la sustitución de un módulo o a un restablecimiento.", "Há uma diferença significativa entre as fontes da ECU; também pode resultar da substituição de um módulo ou de uma reposição.", "Il y a un écart important entre les sources ECU ; il peut aussi résulter d'un remplacement de module ou d'une réinitialisation.", "C'è una differenza significativa tra le fonti ECU; potrebbe anche derivare dalla sostituzione di un modulo o da un reset."),
        R("Fuel unavailable", "Yakıt kullanılamıyor", "Kraftstoff nicht verfügbar", "Paliwo niedostępne", "Combustible no disponible", "Combustível indisponível", "Carburant indisponible", "Carburante non disponibile"),
        R("Before Repair / After Repair comparison", "Onarım Öncesi / Onarım Sonrası karşılaştırması", "Vergleich Vor der Reparatur / Nach der Reparatur", "Porównanie przed naprawą / po naprawie", "Comparación antes / después de la reparación", "Comparação antes / depois da reparação", "Comparaison avant / après réparation", "Confronto prima / dopo la riparazione"),
        R("Generic OBD-II Powertrain ECU: responds", "Genel OBD-II Güç aktarma ECU'su: yanıt veriyor", "Generische OBD-II-Antriebsstrang-ECU: antwortet", "Ogólne ECU układu napędowego OBD-II: odpowiada", "ECU de tren motriz OBD-II genérica: responde", "ECU genérica de motor/transmissão OBD-II: responde", "ECU groupe motopropulseur OBD-II générique : répond", "ECU powertrain OBD-II generica: risponde"),
        R("No code was found in the services read.", "Okunan hizmetlerde kod bulunamadı.", "In den gelesenen Diensten wurde kein Code gefunden.", "W odczytanych usługach nie znaleziono kodu.", "No se encontró ningún código en los servicios leídos.", "Não foi encontrado nenhum código nos serviços lidos.", "Aucun code n'a été trouvé dans les services lus.", "Nessun codice trovato nei servizi letti."),
        R("Press “Read” — the data stored at the moment of the fault will be read from the ECU.", "“Oku”ya basın — arıza anında saklanan veriler ECU'dan okunacak.", "Tippe auf „Lesen“ – die im Moment des Fehlers gespeicherten Daten werden aus der ECU gelesen.", "Naciśnij „Odczyt” — dane zapisane w momencie usterki zostaną odczytane z ECU.", "Pulsa «Leer»: los datos almacenados en el momento de la avería se leerán de la ECU.", "Prima «Ler» — os dados guardados no momento da avaria serão lidos da ECU.", "Appuyez sur « Lire » — les données stockées au moment du défaut seront lues depuis l'ECU.", "Premi «Leggi»: i dati memorizzati nel momento del guasto verranno letti dall'ECU."),
        R("The OBD adapter is not connected. Connect to the car first.", "OBD adaptörü bağlı değil. Önce araca bağlanın.", "Der OBD-Adapter ist nicht verbunden. Verbinde dich zuerst mit dem Auto.", "Adapter OBD nie jest połączony. Najpierw połącz się z samochodem.", "El adaptador OBD no está conectado. Conéctate primero al coche.", "O adaptador OBD não está ligado. Ligue-se primeiro ao carro.", "L'adaptateur OBD n'est pas connecté. Connectez-vous d'abord à la voiture.", "L'adattatore OBD non è connesso. Connettiti prima all'auto."),
        R("Could not read Freeze Frame. Check the OBD connection and ignition, then try again.", "Freeze Frame okunamadı. OBD bağlantısını ve kontağı kontrol edip tekrar deneyin.", "Freeze Frame konnte nicht gelesen werden. Prüfe OBD-Verbindung und Zündung und versuche es erneut.", "Nie udało się odczytać Freeze Frame. Sprawdź połączenie OBD i zapłon, a potem spróbuj ponownie.", "No se pudo leer Freeze Frame. Comprueba la conexión OBD y el contacto y vuelve a intentarlo.", "Não foi possível ler o Freeze Frame. Verifique a ligação OBD e a ignição e tente novamente.", "Impossible de lire le Freeze Frame. Vérifiez la connexion OBD et le contact, puis réessayez.", "Impossibile leggere il Freeze Frame. Controlla la connessione OBD e il quadro, poi riprova."),
        R("No Freeze Frame is stored in the ECU. This is normal when there is no trouble code (DTC) or it was cleared recently.", "ECU'da kayıtlı Freeze Frame yok. Arıza kodu (DTC) yoksa veya yakın zamanda silindiyse bu normaldir.", "In der ECU ist kein Freeze Frame gespeichert. Das ist normal, wenn kein Fehlercode (DTC) vorliegt oder er kürzlich gelöscht wurde.", "W ECU nie zapisano Freeze Frame. To normalne, gdy nie ma kodu usterki (DTC) lub został niedawno skasowany.", "No hay Freeze Frame almacenado en la ECU. Es normal cuando no hay código de avería (DTC) o se borró hace poco.", "Não há Freeze Frame guardado na ECU. É normal quando não existe código de avaria (DTC) ou foi apagado recentemente.", "Aucun Freeze Frame n'est stocké dans l'ECU. C'est normal lorsqu'il n'y a pas de code défaut (DTC) ou qu'il a été effacé récemment.", "Nessun Freeze Frame è memorizzato nell'ECU. È normale quando non c'è un codice guasto (DTC) o è stato cancellato di recente."),
        R("The ECU returned no extra data for this frame.", "ECU bu kare için ek veri döndürmedi.", "Die ECU lieferte keine zusätzlichen Daten für diesen Frame.", "ECU nie zwróciło dodatkowych danych dla tej ramki.", "La ECU no devolvió datos adicionales para este frame.", "A ECU não devolveu dados adicionais para este frame.", "L'ECU n'a renvoyé aucune donnée supplémentaire pour cette trame.", "L'ECU non ha restituito dati aggiuntivi per questo frame."),
